import { useCallback } from 'react';
import { useStore } from '~/app/store/store';
import { ToggleSwitch } from '~/shared/ui/toggle-switch/toggle-switch';

export const ToggleTokenBalanceVisibility = () => {
  const isHideBalance = useStore((state) => state.appConfigSlice.isHideBalance);
  const setIsHideBalance = useStore((state) => state.appConfigSlice.setIsHideBalance);
  const onToggle = useCallback((result: boolean) => {
    setIsHideBalance(result);
  }, []);
  return <ToggleSwitch on={isHideBalance} onToggle={onToggle} />;
};
